INSERT IGNORE INTO info_article (id,article_no,title,channel,content_type,summary,content,author,author_type,cover_icon,tags,read_count,like_count,comment_count,favorite_count,status,risk_level,risk_note,is_top,ai_generated,source,published_at) VALUES
(1,'N-20260627-018','大蒜价格周度分析：库存收紧支撑价格上行','市场动态','图文','本周金乡杂交红蒜均价 4.50 元/斤，周环比上涨 7.1%。主因库内余量低于常年同期三成，出口订单集中到港，预计短期内价格仍有支撑。','一、价格运行情况\n本周（06-21 至 06-27）金乡产区杂交红蒜统货均价 4.50 元/斤，周环比上涨 7.1%，同比上涨 12.4%。分级看，5.5-6.0cm 混级报价 4.40-4.65 元/斤，6.0cm 以上大混级报价 4.80-5.00 元/斤，价差较上周扩大 0.08 元/斤。\n\n二、上涨驱动因素\n1. 库存收紧：截至 6 月 26 日，金乡冷库在库量约 26 万吨，低于常年同期三成，库存周转天数由 30 天降至 15 天。\n2. 出口订单：5 月大蒜出口量环比增长 22%，东南亚与中东订单集中到港，加工厂补库意愿强。\n3. 惜售情绪：农户与经纪人普遍看好后市，出货节奏放缓。\n\n三、后市研判\n短期（7-10 天）价格仍有支撑，预计运行区间 4.40-4.90 元/斤；需关注 7 月上旬新蒜集中上市节奏与冷库出货意愿变化。建议持货商分批出货，避免集中抛售。\n\n数据来源：金乡大蒜交易市场、平台 36 名产地信息员报价、海关出口数据。','行情分析师 · 李耘','official','🧄','大蒜,行情分析,价格周报',12560,243,86,368,'published','none','',TRUE,FALSE,'平台行情数据中心','2026-06-27 08:30'),
(2,'V-20260626-092','大棚草莓冬季管理要点（3分钟教学）','生产技术','短视频','高级农艺师张老师实地讲解大棚草莓冬季温湿度管理、授粉与病害预防的三个关键动作。','【视频脚本摘要】\n0:00-0:35 冬季棚内温度三段管理：夜间不低于 5℃，白天 22-25℃，超过 28℃ 及时通风。\n0:35-1:20 湿度与放风：晴天上午 9 点后放风 30 分钟，相对湿度控制在 60%-70%，降低灰霉病发生。\n1:20-2:20 授粉管理：每 667 ㎡ 放一箱蜜蜂，花期禁用菊酯类杀虫剂。\n2:20-3:12 病害预防：重点防灰霉病与白粉病，交替用药并注意安全间隔期。','农技专家张老师','expert','🍓','草莓,大棚,冬季管理,短视频',89230,6240,412,2180,'published','none','',FALSE,FALSE,'平台农技课堂','2026-06-26 16:00'),
(3,'N-20260626-077','2026年耕地地力保护补贴政策解读：山东补贴标准与申报时间','政策法规','图文','农业农村部、财政部下达 2026 年耕地地力保护补贴资金，山东省补贴标准为每亩不低于 120 元，6 月底前完成兑付。','一、政策要点\n2026 年耕地地力保护补贴继续按照"谁种地、补贴谁"原则发放，补贴对象为实际种粮农民和新型经营主体。\n\n二、山东省执行口径\n1. 补贴标准：每亩不低于 120 元，具体由县级根据资金总量与核定面积确定。\n2. 申报时间：6 月 10 日-6 月 25 日村级登记，6 月 30 日前完成乡镇审核与公示。\n3. 兑付方式：通过"一卡通"直接发放到户。\n\n三、常见问题\nQ：流转土地的补贴归谁？\nA：按流转合同约定，合同未约定的补给实际种植方。\n\nQ：撂荒地能否享受补贴？\nA：不予补贴，且连续撂荒两年以上将取消次年补贴资格。\n\n四、申报材料\n身份证、土地承包经营权证或流转合同、种植面积核定表、"一卡通"账户信息。','政策研究部','official','📜','补贴,政策解读,耕地地力',35680,1102,214,986,'published','none','',FALSE,FALSE,'农业农村部官网（已获授权转载）','2026-06-26 09:15'),
(4,'N-20260625-060','番茄叶片发黄别乱施肥！两种缺素症状的田间鉴别方法','生产技术','图文','缺钾与缺镁都会导致叶片黄化，许多农户凭经验盲目追肥反而加重症状。本文用一组田间对照图教你快速区分。','一、缺钾：老叶边缘先黄\n症状从下部老叶开始，叶缘先出现黄化并逐步向内扩展，后期叶缘焦枯、叶片卷曲。土壤多为砂质、钾素淋失严重地块。\n\n二、缺镁：老叶叶脉间黄化\n叶脉仍保持绿色，脉间组织黄化呈"鱼骨状"，是缺镁的典型特征。多发生在连续大量施用钾肥或土壤偏酸的地块。\n\n三、快速鉴别口诀\n边缘黄、向内扩——缺钾；\n脉绿间黄鱼骨状——缺镁；\n新叶先黄——多为缺铁或缺锌。\n\n四、矫正方案\n缺钾：每亩追施硫酸钾 8-10 公斤，或叶面喷施 0.3% 磷酸二氢钾 2-3 次。\n缺镁：叶面喷施 0.5% 硫酸镁，间隔 7 天连喷 2 次，同时调节土壤 pH 至 6.0-6.5。\n\n提醒：黄化也可能是根结线虫、渍害或病毒病引起，务必结合根系与土壤水分排查。','植保站 · 王农艺师','expert','🍅','番茄,缺素,叶片黄化,田间诊断',21070,1386,268,356,'published','none','',FALSE,FALSE,'县植保植检站','2026-06-25 14:22'),
(5,'Q-20260625-014','6月27日200个品种行情早报','市场动态','行情简报','AI 每日 02:00 基于 200+ 品种实时行情自动生成，06:00 前经人工抽检后发布。','【整体】今日监测 213 个品种，上涨 137 个、下跌 48 个、持平 28 个。蔬菜综合均价 5.62 元/公斤，环比上涨 2.4%。\n\n【领涨】辣椒 +8.3%（河南商丘，南方降雨影响采收）；大蒜 +7.1%（山东金乡，库存收紧）；生姜 +6.1%（山东莱芜，出口订单增加）。\n\n【领跌】西红柿 -4.1%（河北邯郸，设施菜集中上市）；黄瓜 -3.8%（山东寿光）；白菜 -2.5%（河北唐山）。\n\n【提示】葱姜蒜类集体走强，建议持货商分批出货；叶菜类短期承压，采购方可适当补充库存。','AI内容工厂','ai','📊','日报,行情,200品种',45210,2035,186,742,'published','low','AI 生成内容，已通过 10% 人工抽检',FALSE,TRUE,'平台 AIGC 管线','2026-06-27 06:00'),
(6,'L-20260625-031','直播回放：夏季番茄病害防治专场','生产技术','直播','李园艺专家讲解夏季高温高湿条件下番茄晚疫病、灰霉病与病毒病的识别与用药方案。','【直播要点】\n1. 晚疫病：低温高湿型病害，重点在连阴雨前后预防，推荐烯酰吗啉、氟啶胺交替使用。\n2. 灰霉病：花期是防治关键窗口，注意棚内湿度与残花清理。\n3. 病毒病：以防控传毒媒介（烟粉虱、蚜虫）为主，配合抗病毒制剂。\n4. 用药安全：严格执行安全间隔期，采收前 7 天停止用药。\n\n【互动问答】共回答观众提问 46 个，涉及药剂配比、抗性治理与有机种植替代方案。','李园艺','expert','🎬','番茄,病害防治,直播回放',12048,892,164,428,'published','none','',FALSE,FALSE,'平台直播课堂','2026-06-25 20:00'),
(7,'N-20260627-021','2024年一号文件深度解读（图文 · 3,200字）','政策法规','图文','围绕粮食安全与乡村振兴，解读一号文件对新型经营主体的支持政策。','稿件正文略。文中涉及耕地地力保护补贴金额表述，需与农业农村部原文核对后发布。','政策研究部','official','📜','一号文件,政策解读',0,0,0,0,'pending','medium','敏感词命中 2 处；补贴金额表述与原文存在出入风险',FALSE,FALSE,'政策研究部','2026-06-27 09:40'),
(8,'V-20260627-005','"包治百病"特效杀菌剂推广（短视频 01:30）','生产技术','短视频','UGC 投稿，宣称杀菌剂可"包治百病"，疑似违禁夸大宣传。','稿件正文略。视频内容存在绝对化用语与疗效承诺，需人工复核。','UGC 用户 159****8810','ugc','🎬','农资,杀菌剂',312,8,12,3,'pending','high','高风险：违禁夸大宣传；图片鉴黄正常',FALSE,FALSE,'用户投稿','2026-06-27 08:12'),
(9,'N-20260627-015','草莓高产种植技术全流程（图文 · 12张图）','生产技术','图文','从育苗、定植到采收的草莓高产管理全流程，适合新种植户系统学习。','一、品种选择：红颜、章姬为主栽品种，搭配香野作为授粉品种。\n二、育苗：4 月母株定植，7 月前完成子苗繁育，注意炭疽病预防。\n三、定植：8 月下旬至 9 月上旬，株距 18-20cm，深不埋心、浅不露根。\n四、田间管理：温度、湿度、水肥一体化三线管理，花期放蜂授粉。\n五、采收：果实着色 70% 以上采收，冷链运输温度 2-5℃。','农技专家张老师','expert','🍓','草莓,高产,全流程',0,0,0,0,'pending','low','机器通过，转人审：新作者首发',FALSE,FALSE,'平台农技课堂','2026-06-27 07:55'),
(10,'N-20260620-118','某夸大宣传"神奇农药"图文','生产技术','图文','命中敏感词规则 S-07，机器复核疑似违规，已下架。','稿件正文略。','UGC 用户 138****6620','ugc','📜','农资',312,8,2,1,'offline','high','命中敏感词规则 S-07，已下架',FALSE,FALSE,'用户投稿','2026-06-20 11:08'),
(11,'N-20260624-041','山东寿光西红柿产地直供考察记','企业动态','图文','走访寿光三家合作社，了解产地直供的品控与分级标准。','【考察背景】6 月中旬走访寿光稻田镇、洛城街道三家西红柿合作社，重点了解产地直供的品控与分级标准。\n\n【品控要点】\n1. 分级：按果径与色泽分三级，一级果果径 70-80mm、着色均匀。\n2. 采后：采后 2 小时内预冷至 12℃，冷链车 24 小时内发往京津市场。\n3. 追溯：每箱贴溯源码，可查地块、采收日期与检测报告。\n\n【结论】产地直供模式可减少 2 个中间环节，综合损耗率由 12% 降至 6%。','绿源蔬菜合作社','org','🍅','西红柿,产地直供,合作社',6840,286,42,128,'published','none','',FALSE,FALSE,'平台产业观察','2026-06-24 10:20'),
(12,'N-20260623-033','国际农业：东南亚大蒜进口需求回暖','国际农业','图文','越南、印尼采购商询盘量环比增长 30%，出口报价小幅上行。','【市场概况】6 月以来东南亚大蒜进口询盘量环比增长约 30%，主要来自越南、印尼与泰国。\n\n【价格】CFR 报价 1180-1250 美元/吨，较上月上涨 3%-5%。\n\n【风险提示】海运运价波动与目的国检疫政策变化是主要不确定性，建议出口企业锁定远期汇率与运价。','行情分析师 · 李耘','official','🌍','国际,大蒜,出口',4260,164,28,86,'published','none','',FALSE,FALSE,'平台国际行情组','2026-06-23 15:40');
