INSERT IGNORE INTO info_knowledge (id,title,category,crop,summary,content,source_name,view_count,tags,status,updated_at) VALUES
(1,'大蒜叶枯病识别与防治','病虫害防治','大蒜','叶片由叶尖向基部干枯，湿度大时病部产生黑色霉层，与冻害、缺钾症状易混淆。','【症状】多从叶尖或叶缘开始，初为灰白色小斑点，后扩展为不规则条斑，湿度大时病部产生黑色霉层。\n【发病条件】日均温 15-20℃、连阴雨或田间湿度大时流行。\n【防治】1) 轮作 2-3 年；2) 发病初期用苯醚甲环唑或嘧菌酯喷雾，7-10 天一次，连喷 2 次；3) 雨后及时排水，避免偏施氮肥。','省农科院蔬菜研究所',8624,'大蒜,叶枯病,真菌病害','published','2026-06-20'),
(2,'水稻稻飞虱防治指标与用药','病虫害防治','水稻','分蘖期百丛虫量 1000 头、孕穗期 1500 头即需防治，优先选用三氟苯嘧啶等高效低风险药剂。','【防治指标】分蘖期百丛虫量 1000 头，孕穗至抽穗期 1500 头。\n【用药】三氟苯嘧啶、吡蚜酮、烯啶虫胺，注意轮换用药延缓抗性。\n【注意事项】保护天敌，避免田埂除草过度；施药时保持 3-5cm 浅水层。','县植保植检站',6218,'水稻,稻飞虱,防治指标','published','2026-06-18'),
(3,'番茄缺钾与缺镁的田间鉴别','营养管理','番茄','缺钾从老叶叶缘向内黄化焦枯；缺镁叶脉保持绿色、脉间黄化呈鱼骨状。','【缺钾】老叶叶缘先黄化，向内扩展，后期焦枯卷曲。\n【缺镁】叶脉绿、脉间黄，呈鱼骨状。\n【矫正】缺钾每亩追施硫酸钾 8-10kg；缺镁叶面喷 0.5% 硫酸镁，7 天一次连喷 2 次。','省农科院蔬菜研究所',9456,'番茄,缺钾,缺镁,叶片黄化','published','2026-06-15'),
(4,'冷库大蒜储存温湿度控制要点','采后处理','大蒜','入库前充分晾晒至外皮干燥，库温 -1~0℃、相对湿度 65%-70%，避免与果蔬混储。','【入库标准】外皮干燥、无机械伤，含水量降至 65% 以下。\n【温湿度】库温 -1~0℃，相对湿度 65%-70%，波动不超过 ±0.5℃。\n【管理】定期通风换气，避免与呼吸强度高的果蔬混储；出库前缓慢回温，防止结露。','金乡大蒜产业协会',4826,'大蒜,冷库,储存','published','2026-06-12'),
(5,'小麦赤霉病预防关键窗口','病虫害防治','小麦','抽穗至扬花初期是唯一有效预防窗口，见花打药，遇连阴雨需 5-7 天后补喷。','【关键窗口】抽穗至扬花初期，见花打药。\n【用药】氰烯菌酯、丙硫菌唑、戊唑醇，交替使用。\n【补喷】施药后 6 小时内遇雨需补喷；连阴雨天气 5-7 天后补喷一次。','县植保植检站',7320,'小麦,赤霉病,预防','published','2026-06-10'),
(6,'设施大棚夏季降温三件套','设施管理','蔬菜','遮阳网 + 湿帘风机 + 顶部通风组合降温，配合早晚滴灌可降低棚温 5-8℃。','【遮阳】外遮阳网遮光率 40%-50%，上午 10 点至下午 4 点覆盖。\n【通风】顶部放风口与侧窗对流，配合湿帘风机降温。\n【水分】早晚滴灌，避免中午高温浇水；可配合行间喷雾。\n【效果】组合措施可降低棚温 5-8℃，减轻日灼与落花。','省农科院蔬菜研究所',5684,'大棚,降温,夏季管理','published','2026-06-08');
INSERT IGNORE INTO info_qa_record (id,qa_no,qa_type,question,answer,category,crop,source_refs,confidence,expert_name,status,asked_by,created_at) VALUES
(1,'QA20260627001','ai','大蒜叶片发黄，从叶尖开始干枯，是什么病？','从描述看，重点排查大蒜叶枯病与冻害、缺钾三类原因。叶枯病多从叶尖或叶缘开始，初为灰白色小斑点后扩展为不规则条斑，湿度大时病部有黑色霉层；冻害则整片叶尖均匀失水发白；缺钾表现为老叶叶缘黄化并逐步向内扩展。建议：1) 拍摄 3 片病叶正反面并记录连续阴雨天数；2) 先隔离病株，避免盲目混配农药；3) 如确诊叶枯病，可用苯醚甲环唑或嘧菌酯喷雾，7-10 天一次连喷 2 次。如 24 小时内扩散明显，建议转农艺专家复核。','病虫害防治','大蒜','农技知识库《大蒜叶枯病识别与防治》；平台行情·大蒜主产区病害预警',92,'AI农技助手','answered','王建国','2026-06-27 09:20:00'),
(2,'QA20260626002','ai','番茄果实脐部发黑是什么原因？','这是典型的脐腐病，属生理性病害，主因是钙素吸收受阻而非土壤缺钙。常见诱因：1) 土壤水分剧烈波动；2) 氮肥或钾肥过量抑制钙吸收；3) 空气干燥、蒸腾过强。建议：保持土壤湿度稳定（滴灌小水勤浇）、控制氮钾用量、叶面喷施 0.3% 氯化钙或硝酸钙 2-3 次（重点喷幼果），并避免高温强光时段整枝。','营养管理','番茄','农技知识库《番茄缺钾与缺镁的田间鉴别》；平台病害图谱',88,'AI农技助手','answered','刘志强','2026-06-26 15:40:00'),
(3,'QA20260625003','expert','柑橘园红蜘蛛反复发生，用什么药？','红蜘蛛抗性上升快，关键是轮换与杀卵兼顾。建议方案：1) 冬季清园用矿物油 + 炔螨特；2) 春季发生初期用螺螨酯（杀卵）配合乙螨唑；3) 每季同一作用机理药剂不超过 2 次；4) 喷药重点叶背，用水量要足。注意保护捕食螨，避免广谱杀虫剂连用。','病虫害防治','柑橘','—',96,'王新民','answered','陈小满','2026-06-25 10:12:00'),
(4,'QA20260624004','ai','小麦收割后什么时候卖价格比较好？','结合平台行情与托市政策：当前新麦开秤价 2.56 元/公斤，容重 770g/L 以上可达到 2.60-2.64 元/公斤。近 7 日预测中值 2.59 元/公斤，上涨概率 58%。建议：1) 水分达标（≤13%）后及时售粮，避免后期仓容紧张与霉变风险；2) 若仓储条件良好，可留存 30%-40% 至 9-10 月观察托市收购节奏；3) 关注当地中储粮挂牌价变化作为出货信号。','行情决策','小麦','平台行情·小麦 7 日预测；中储粮挂牌价；农技知识库《小麦赤霉病预防关键窗口》',86,'AI农技助手','answered','李丰收','2026-06-24 16:05:00');
